import{_ as a,o as e,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CephFS Code Walkthrough: rstats","description":"","frontmatter":{"title":"CephFS Code Walkthrough: rstats","date":"2021-08-20T00:00:00.000Z","updated":"2021-08-21T00:00:00.000Z","tags":["CephFS","R","Stats","scrubbing","distributed storage","file system check"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/CephFS_Code_Walkthrough_-_rstats.md","filePath":"posts/2021/CephFS_Code_Walkthrough_-_rstats.md","lastUpdated":1780459816000}'),i={name:"posts/2021/CephFS_Code_Walkthrough_-_rstats.md"};function s(r,t,d,n,h,p){return e(),l("div",null,[...t[0]||(t[0]=[o('<p>CephFS R-Stats 实现讨论会议纪要</p><h3 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h3><p>本次会议深入探讨了 Ceph 文件系统（CephFS）中递归树统计（R-Stats）的实现细节，以及其在文件系统检查中的应用。</p><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><ol><li><p><strong>R-Stats 的定义与用途</strong>：</p><ul><li>R-Stats 用于递归前向 scrubbing 过程中检查统计数据的一致性。</li><li>提出使用快照 R-Stats 来检测两个文件系统树之间的变更。</li></ul></li><li><p><strong>Scrubbing 的启动方式</strong>：</p><ul><li>Scrubbing 可针对常规目录或内部 MDS 目录启动，若无递归标志，仅验证目录的一层。</li></ul></li><li><p><strong>R-Stats 的维护与结构</strong>：</p><ul><li>维护依赖于 <code>frag_info</code> 和 <code>nest_info</code> 结构，这些结构嵌入在 <code>fnode_t</code> 容器结构中。</li><li><code>frag_info</code> 维护单个目录片段的信息，<code>nest_info</code> 累积深度超过一层的条目统计。</li></ul></li><li><p><strong>R-Stats 的传播</strong>：</p><ul><li>从叶节点向文件系统根节点传播，涉及路径上所有 <code>fnode</code> 对象的更新。</li><li>传播是懒惰的，不即时发生。</li></ul></li><li><p><strong>挑战与问题</strong>：</p><ul><li>R-Stats 传播涉及大量锁定，是并发问题。</li><li>快照目录的 RC 时间更新存在 bug。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>承认 R-Stats 在文件系统检查和快照变更检测中的重要性。</li><li>需要解决 R-Stats 传播中的锁定和并发问题。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>调查和修复快照目录的 RC 时间更新 bug。</li><li>研究优化 R-Stats 传播过程中的锁定机制，提高效率和可靠性。</li></ul><h3 id="会议总结" tabindex="-1">会议总结 <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结&quot;">​</a></h3><p>会议强调了 R-Stats 在 CephFS 中的关键作用，并明确了后续改进的方向。</p>',11)])])}const _=a(i,[["render",s]]);export{c as __pageData,_ as default};
